<?php
$zipData = base64_decode('');
file_put_contents('deploy.zip', $zipData);
$zip = new ZipArchive;
if ($zip->open('deploy.zip') === TRUE) {
    // Extract everything to the parent directory where public/ is located
    $zip->extractTo('../');
    $zip->close();
    unlink('deploy.zip');
    echo '<h1>Design & Gradient Fix Deployed!</h1>';
    echo '<p>The dark mode gradients and Kitchen Display colors are now perfect!</p>';
} else {
    echo '<h1>Error extracting zip</h1>';
}
?>